entries[219300] = { ["name"] = "Skarmorak Shard", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Strength\nUse: Grasp the shard tightly to enrich yourself with crystalline energy, increasing your Mastery by 2756 for 15 sec. (1 Min, 30 Sec Cooldown)\nEquip: The shard draws in remnant energy from defeated enemies, increasing your Mastery by 58 for 15 sec, up to 5 times.\nSell Price:" }
entries[219301] = { ["name"] = "Overclocked Gear-a-Rang Launcher", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nUse: Launch the superheated gear-a-rang, inflicting ( 1 * 41390 ) Flamestrike damage to enemies, losing heat as it cuts through them. (2 Min Cooldown)\nEquip: Your melee attacks have a chance to crank the launcher's gears, decreasing its cooldown by 5 sec and heating up your weapon which causes your next attack to inflict ( 1 * 23306 ) additional Fire damage.\nSell Price:" }
entries[219302] = { ["name"] = "Scrapsinger's Symphony", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Intellect\nEquip: Your healing abilities have a chance to call the nearby metal to form a shield around an ally, absorbing 45216 damage.\n\nThe shield reacts explosively to fire, inflicting 4162 Fire damage to nearby enemies when struck.\nSell Price:" }
entries[219303] = { ["name"] = "High Speaker's Accretion", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 604 Mastery\nUse: Charge the crystal to summon a rift that draws power from nearby enemies, inflicting ( 1 * 45046 * 6) Shadow damage over 6 sec.\n\nWhen the rift collapses, its drawn energy returns to you to increase your Intellect by 135 for 20 sec, further increased for each enemy struck. (2 Min Cooldown)\nSell Price:" }
entries[219304] = { ["name"] = "Conductor's Wax Whistle", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Agility\nEquip: Your attacks have a chance to direct a Kobold Cart towards your target, sending a careening troop that collides with enemies, inflicting ( 1 * 61010 ) Physical damage split between enemies impacted.\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\n\"A hero's symbolic trophy, for the kobolds need not be summoned. The kobolds yearn for the catacombs.\"\nSell Price:" }
entries[219305] = { ["name"] = "Carved Blazikon Wax", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Intellect\nEquip: Your spells have a chance to imbue the wax, causing it to form into a blazing candle for 15 sec which increases your Versatility by 1292 , further increased by 339 while you remain within its light.\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:" }
entries[219306] = { ["name"] = "Burin of the Candle King", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Intellect\nUse: Carve a wax copy of your target, which absorbs 50% of their damage taken. The absorption heats up the wax, causing it to melt after absorbing 264398 damage. (1 Min, 30 Sec Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:" }
entries[219307] = { ["name"] = "Remnant of Darkness", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nEquip: Your abilities have a chance to call the Darkness to you, increasing your Primary Stat by 281 , up to ( 281 * 5).\n\nUpon reaching full power, the Darkness is unleashed, inflicting ( 1 * 35879 * 15 / 3) Shadow damage split between nearby enemies over 15 sec before fading back into the remnant.\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:" }
entries[219308] = { ["name"] = "Signet of the Priory", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 [Agility or Strength or Intellect]\nUse: Raise your signet to the Light, increasing your highest secondary stat by 2756 for 20 sec. Your act inspires nearby signetbearers within your party, granting them 73 of the same stat for 20 sec. (2 Min Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nComplete Priory of the Sacred Flame within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:" }
entries[219309] = { ["name"] = "Tome of Light's Devotion", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nEquip: Advance to the 50 Verses of Inner Resilience, reading as you are attacked.\nInner Resilience increases your armor by 1438 and grants your attacks a chance to invoke a ward which absorbs 67723 Magic damage. When finished, sift through the passages to another chapter.\n\nValid only for tank specializations. (500ms cooldown)\nUse: Sift through the passages in the tome with increased Radiance . (1 Min, 30 Sec Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nComplete Priory of the Sacred Flame within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:" }
entries[219310] = { ["name"] = "Bursting Lightshard", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Intellect\nUse: Summon a Bursting Lightspawn which sacrifices its health to unleash Bursts of Light, inflicting 57024 Holy damage split between nearby enemies every 2 sec while it lives. (2 Min Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nComplete Priory of the Sacred Flame within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:" }
entries[219311] = { ["name"] = "Void Pactstone", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Strength\nEquip: Your attacks have a chance to call to the pact, exploding for ( 1 * 35361 ) Shadow damage split between nearby enemies and increasing your Haste by 377 for 10 sec.\n\nYour death breaks the pact, causing a violent explosion.\nComplete the Dawnbreaker within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:" }
entries[219312] = { ["name"] = "Empowering Crystal of Anub'ikkaj", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 [Agility or Intellect]\nEquip: Your spells and abilities have a chance to let loose a nascent empowerment from the crystal, increasing a random secondary stat by 1392 for 20 sec.\nComplete the Dawnbreaker within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:" }
entries[219313] = { ["name"] = "Mereldar's Toll", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Intellect\nUse: Release a toll of holy light upon the target, inflicting ( 1 * 53941 ) Holy damage. The next 5 allies to attack the target will receive the Blessing of Mereldar, increasing their Versatility by 658 for 10 sec. (1 Min, 30 Sec Cooldown)\nComplete the Dawnbreaker within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:" }
entries[219314] = { ["name"] = "Ara-Kara Sacbrood", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 604 Haste\nEquip: Your abilities have a chance to stir the sac, releasing an egg which grants you 213 Primary Stat. Each egg hatches after 1 min, and the new brood attacks your next target, inflicting ( 1 * 1598 * 8) Nature damage over 8 sec. (100ms cooldown)\nComplete Ara-kara, City of Echoes within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:" }
entries[219315] = { ["name"] = "Refracting Aggression Module", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 [Agility or Strength]\nEquip: Your taunt abilities activate the module's refracting energy, protecting you from 50% of damage taken, up to 301603 . This may only occur once every 1 min.\n\nValid only for tank specializations. (1m cooldown)\nSell Price:" }
entries[219316] = { ["name"] = "Ceaseless Swarmgland", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 [Agility or Strength]\nEquip: The gland releases pheromones that attract a Ceaseless Swarm of insects to surround you. Taking damage has a high chance to retaliate against attackers, inflicting ( 2726 * 6) Nature damage over 6 sec and reducing damage dealt to you by 3781 .\nComplete Ara-kara, City of Echoes within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:" }
entries[219317] = { ["name"] = "Harvester's Edict", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 [Agility or Intellect]\nEquip: Your damaging spells and abilities have a chance to send an orb of volatile black blood drifting to your target, exploding for ( 1 * 55918 ) Shadow damage split between all nearby enemies on impact. Intercepting the orb allows you to siphon its power, instead increasing your Mastery by 1653 for 15 sec.\nComplete Ara-kara, City of Echoes within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:" }
entries[219318] = { ["name"] = "Oppressive Orator's Larynx", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nEquip: Your attacks have a chance to stir the larynx, allowing its dark whispers to influence you. Each whisper flows through your mind for 30 sec, granting 198 Strength.\nUse: Wave the larynx in the air to release a tormenting chorus, inflicting ( 1 * 58370 * 3) Shadow damage over 3 sec split between nearby enemies. Your whispers leave to join the chorus, increasing its damage before falling silent. (2 Min Cooldown)\nSell Price:" }
entries[219319] = { ["name"] = "Twin Fang Instruments", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Agility\nUse: Open the pouch and draw Nx's shadow blade to quickly strike at enemies in front of you, inflicting ( 1 * 23075 ) Shadow damage to all enemies hit.\n\nYou may use the pouch up to two additional times within 20 sec before it seals itself to magically recharge its contents. (2 Min Cooldown)\nSell Price:" }
entries[219320] = { ["name"] = "Viscous Coaglam", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Intellect\nEquip: Your excessive healing attracts nearby shadow energy to your party, storing up to 8407 healing and restoring the target's health when they receive damage.\nUse: Channel the coaglam's power, concentrating all current shadow energy to shield your target. (1 Min Cooldown)\nSell Price:" }
entries[219321] = { ["name"] = "Cirral Concoctory", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Intellect\nEquip: Your spells have a chance to inspire you to experiment on an ally, enhancing them in unforeseen ways for 20 sec.\nSell Price:" }
