entries[219381] = { ["name"] = "Fate Weaver", ["text"] = "The War Within Season 1\nBinds when picked up\nUnique-Equipped\nHeld In Off-hand\n+394 Intellect\n+208 Stamina\n+ 125 Haste\n+ 114 Versatility\n\"Barely legible words are inscribed on the handle. \"The ritual site lies in Azj-Kahet overlooking the Salien Gutters, far North of Rak-Zakaz.\"\"\nSell Price:" }
entries[219382] = { ["name"] = "Fateweaved Needle", ["text"] = "Binds when picked up\nOne-Hand Dagger\n98 - 164 Damage Speed 1.80\n(72.8 damage per second)\n+748 Intellect\n+208 Stamina\nDurability 80 / 80\nEquip: Your harmful and helpful spells have a chance to weave a Thread of Fate between you and your target for 5 sec. Tethered allies gain 299 bonus primary while the Thread holds and enemies take ( 1 * 8615 ) Cosmic Damage when the Thread breaks.\nSell Price:" }
