entries[219384] = { ["name"] = "Tenir and the Order of Night", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"A ten-hour epic in three acts.\"" }
entries[219385] = { ["name"] = "Antiparalytic Serum", ["text"] = "Quest Item\nUse: Administer the Antiparalytic Serum to a target paralyzed by The Puppetmaster's draught.\n\"A serum to cure paralysis. (Efficacy may vary.)\"" }
entries[219386] = { ["name"] = "Locus of Power", ["text"] = "Meta Gem\nBinds when picked up\nUnique\nEquip: Learn the following spell.\n\nLocus of Power\nChannel arcane power for 4 sec. Every 0.40 sec, infuse yourself and 2 allies within 50 yards with Haste, Critical Strike, and Mastery for 30 sec.\nRequires level 10 to 80 ( 80)\n\"Fits in a Meta socket.\"" }
entries[219387] = { ["name"] = "Barrel of Fireworks", ["text"] = "Toy\nUse: Deploy a dangerous barrel of fireworks for 5 min so you and your friends can violently illuminate the night sky!\n\nOther players can opt-in to seeing the fireworks by attacking the barrel.\n\nCooldown reduced during drunken goblin revelries. (1 Hour Cooldown)\nSell Price:" }
entries[219388] = { ["name"] = "Sacred Flame Torch", ["text"] = "Quest Item\nUse: Rally a nearby group of Arathi with their faith in the Sacred Flame!\n\"The torch burns with Light, its snapping and flickering almost sounding like a song.\"" }
entries[219389] = { ["name"] = "Lightning Rod", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: Your abilities have a chance to apply Lightning Rod to your target. Allies are granted Critical Strike for 10 sec and enemies suffer Nature damage every 2 sec for 8 sec. When Lightning Rod ends, it returns to you, granting Critical Strike for 10 sec.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[219390] = { ["name"] = "Set Keystone Map: Grim Batol", ["text"] = "Duration: 12 hrs (real time)\nUse: Set the dungeon map of a Mythic Keystone to Grim Batol.\nSell Price:" }
entries[219391] = { ["name"] = "Delver's Dirigible", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Delver's Dirigible.\n\nThis mount can use Ride Along.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This aircraft will help you delve straight into adventure, wherever it may be!\"\nQuest:\nShip It!\nZone:\nIsle of Dorn" }
entries[219392] = { ["name"] = "Flameflow 7000", ["text"] = "Quest Item\nUse: Reveal a flamethrower to deal Fire damage in a cone in front of you for 3 sec. Works against the Mmarl invasive nest-makers. (6 Sec Cooldown)\n\"Gazlowe's flamethrower is guaranteed to work on the bugs in Mmarl's cave.\"" }
