entries[219915] = { ["name"] = "Foul Behemoth's Chelicera", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+1,914 [Agility or Strength]\nUse: Inject an enemy with digestive venom, dealing 617919 Nature damage over 20 sec. While active, your attacks and abilities against the target restore 32184 health. Cannot occur more than every 1 sec.\n\nOverhealing from this effect permanently increases your maximum health by the same amount, becoming an absorb shield upon leaving combat. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[219916] = { ["name"] = "Bronzebeard Family Compass", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 1,171 Mastery\nUse: Get your bearings and meet up with Brann, who heroically swoops in to deliver a for 1769479 Physical damage then granting you 19525 Primary Stat for 10 sec before exiting.\n\nIf already by your side Brann will proudly direct you towards adventure! Immediately repositioning, granting himself 50% additional damage for 10 sec, and performing a .\n\n: (2 Min Cooldown)\n\"A symbol of adventure, discovery, and camaraderie. Intrusted to you by Brann Bronzebeard himself.\"\nSell Price:" }
entries[219917] = { ["name"] = "Creeping Coagulum", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+1,914 Intellect\nUse: Feed the Coagulum, redirecting 20% of all healing done until ( 2828996 * 40 / 100) healing has been consumed. Once sated, the Coagulum bursts to heal 5 allies for [source value].\n\nLingering effluvia causes affected allies' next attacks to deal an additional 20151 Shadow damage, increased based on overhealing done by the Coagulum. (1 Min, 30 Sec Cooldown)\nSell Price:", ["unresolvedValues"] = true }
